// C program for the function called sudoku_set_cell
// Contains target function implementation and dependency signatures

#include <assert.h>
#include <inttypes.h>
#include <math.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct sudoku
{
    uint8_t *a; /**< matrix as a flattened 1D row-major array */
    uint8_t N;  /**< number of elements */
    uint8_t N2; /**< block of elements */
};

// Target function implementation
bool sudoku_set_cell(struct sudoku *s, int row, int col, uint8_t value)
{
    if (s == NULL || s->a == NULL)
        return false;
    if (row < 0 || row >= s->N || col < 0 || col >= s->N)
        return false;

    s->a[row * s->N + col] = value;
    return true;
}

